def is_palindrome(s):
    filtered = []
    for ch in s:
        if ch.isalnum():
            filtered.append(ch.lower())              # keep only letters and digits, ignore case
    cleaned = "".join(filtered)
    return cleaned == cleaned[::-1]                    # compare the cleaned string to its own reverse


