bool isPalindrome(string s) {
    string cleaned;
    for (char ch : s) {
        if (isalnum(ch)) {
            cleaned += tolower(ch);                         // keep only letters and digits, ignore case
        }
    }
    string reversed = cleaned;
    reverse(reversed.begin(), reversed.end());
    return cleaned == reversed;                            // compare the cleaned string to its own reverse
}

