import java.util.*;

public class Main {
    boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {
                left++;                                            // skip non alphanumeric characters from the left
            }
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {
                right--;                                           // skip non alphanumeric characters from the right
            }
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
                return false;                                       // a real mismatch, not a palindrome
            }
            left++;
            right--;
        }
        return true;                                              // the pointers met without ever mismatching
    }

    public static void main(String[] args) {
        String s = "A man, a plan, a canal: Panama";
        Main solution = new Main();
        System.out.println(solution.isPalindrome(s));
    }
}

